input.content:
:root {
  --green: #006a4e;
  --green-deep: #043b2a;
  --green-bright: #12a05f;
  --red: #f42a41;
  --cream: #fff7e6;
  --gold: #ffcf4a;
  --ink: #08211a;
  --hud-font: "Lato", "Liberation Sans", "DejaVu Sans", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--green-deep);
  color: var(--cream);
  font-family: var(--hud-font);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

canvas#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

/* ------------------------------- HUD ------------------------------- */
.hud {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 12px;
  padding: calc(12px + env(safe-area-inset-top)) calc(14px + env(safe-area-inset-right)) 0 calc(14px + env(safe-area-inset-left));
  pointer-events: none;
  transition: opacity .3s ease;
}

body[data-state="menu"] .hud { opacity: .35; }

.hud-left { display: flex; align-items: center; gap: 10px; min-width: 0; }

.flag {
  width: 46px;
  height: 30px;
  flex: 0 0 auto;
  border-radius: 3px;
  background: #006a4e;
  position: relative;
  box-shadow: 0 2px 10px rgba(0, 0, 0, .35), inset 0 0 0 1px rgba(255, 255, 255, .14);
}
.flag::after {
  content: "";
  position: absolute;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #f42a41;
  left: 30%;
  top: 50%;
  transform: translate(-50%, -50%);
}
.flag-lg { width: 72px; height: 46px; border-radius: 5px; }
.flag-lg::after { width: 20px; height: 20px; }

.brand {
  display: flex;
  flex-direction: column;
  line-height: .92;
  letter-spacing: .16em;
  text-shadow: 0 2px 8px rgba(0, 0, 0, .45);
}
.brand strong { font-size: 15px; font-weight: 900; }
.brand span { font-size: 9px; font-weight: 700; color: var(--gold); letter-spacing: .32em; }

.scoreboard {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1;
  padding: 5px 22px 8px;
  border-radius: 16px;
  background: linear-gradient(180deg, rgba(2, 24, 17, .78), rgba(2, 24, 17, .42));
  border: 1px solid rgba(255, 255, 255, .12);
  box-shadow: 0 10px 30px rgba(0, 0, 0, .25);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.scoreboard .label {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .34em;
  color: rgba(255, 247, 230, .6);
  margin-bottom: 3px;
}
.scoreboard b {
  font-size: clamp(24px, 4.2vw, 34px);
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  letter-spacing: .04em;
  color: var(--cream);
  text-shadow: 0 2px 0 rgba(0, 0, 0, .25);
}
.scoreboard b.bump { animation: bump .18s ease; }
@keyframes bump { 50% { transform: scale(1.14); color: var(--gold); } }
.scoreboard .best {
  margin-top: 3px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .2em;
  color: rgba(255, 247, 230, .55);
}
.scoreboard .best i { font-style: normal; color: var(--gold); }

.hud-right {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  pointer-events: auto;
}
.speedo {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  line-height: .9;
  margin-right: 2px;
  padding: 5px 10px;
  border-radius: 10px;
  background: rgba(2, 24, 17, .5);
  border: 1px solid rgba(255, 255, 255, .1);
}
.speedo b { font-size: 20px; font-weight: 900; font-variant-numeric: tabular-nums; }
.speedo span { font-size: 7px; font-weight: 800; letter-spacing: .24em; color: var(--gold); }

.icon-btn {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, .16);
  background: rgba(2, 24, 17, .55);
  color: var(--cream);
  font-family: inherit;
  font-size: 13px;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  transition: background .15s ease, transform .15s ease;
}
.icon-btn:hover { background: rgba(18, 160, 95, .55); }
.icon-btn:active { transform: scale(.94); }
.icon-btn.muted { color: rgba(255, 247, 230, .4); text-decoration: line-through; }

/* --------------------------- Touch controls --------------------------- */
.touch-controls {
  position: fixed;
  z-index: 12;
  left: 0;
  right: 0;
  bottom: calc(18px + env(safe-area-inset-bottom));
  padding: 0 calc(18px + env(safe-area-inset-left)) 0 calc(18px + env(safe-area-inset-right));
  display: flex;
  justify-content: space-between;
  pointer-events: none;
  transition: opacity .25s ease;
}
body[data-state="menu"] .touch-controls,
body[data-state="over"] .touch-controls,
body[data-state="paused"] .touch-controls { opacity: 0; pointer-events: none; }

.steer {
  pointer-events: auto;
  width: clamp(58px, 9vw, 76px);
  height: clamp(58px, 9vw, 76px);
  border-radius: 50%;
  border: 1.5px solid rgba(255, 247, 230, .35);
  background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, .2), rgba(3, 40, 28, .68));
  color: var(--cream);
  font-size: clamp(20px, 3vw, 26px);
  line-height: 1;
  cursor: pointer;
  box-shadow: 0 8px 24px rgba(0, 0, 0, .3), inset 0 0 0 4px rgba(0, 0, 0, .1);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  touch-action: manipulation;
  transition: transform .08s ease, background .1s ease;
}
.steer:active {
  transform: scale(.93);
  background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, .35), rgba(0, 106, 78, .85));
  border-color: var(--gold);
}

/* ------------------------------ Overlays ------------------------------ */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(16px + env(safe-area-inset-top)) 16px calc(16px + env(safe-area-inset-bottom));
  background:
    radial-gradient(ellipse at 50% 62%, rgba(2, 25, 17, .18), rgba(2, 18, 12, .72) 70%),
    linear-gradient(180deg, rgba(2, 26, 18, .4), rgba(2, 20, 14, .76));
  transition: opacity .25s ease;
}
.overlay.hidden { opacity: 0; pointer-events: none; }

.screen { width: 100%; display: flex; justify-content: center; }
.screen.hidden { display: none; }

.menu-card {
  position: relative;
  width: min(480px, 100%);
  max-height: calc(100dvh - 32px - env(safe-area-inset-top) - env(safe-area-inset-bottom));
  overflow-y: auto;
  padding: clamp(22px, 4.4vh, 38px) clamp(20px, 5vw, 42px) clamp(20px, 3.6vh, 32px);
  border-radius: 26px;
  border: 1px solid rgba(255, 247, 230, .16);
  background:
    linear-gradient(160deg, rgba(8, 54, 38, .94), rgba(2, 28, 19, .96) 60%),
    radial-gradient(circle at 80% 0%, rgba(18, 160, 95, .35), transparent 55%);
  box-shadow: 0 30px 80px rgba(0, 0, 0, .48), inset 0 1px 0 rgba(255, 255, 255, .1);
  text-align: center;
  animation: cardIn .5s cubic-bezier(.2, .9, .3, 1.1) both;
  scrollbar-width: none;
}
.menu-card::-webkit-scrollbar { display: none; }

.menu-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 24px;
  right: 24px;
  height: 4px;
  border-radius: 0 0 4px 4px;
  background: linear-gradient(90deg, var(--green-bright), var(--gold) 55%, var(--red));
}

@keyframes cardIn {
  from { opacity: 0; transform: translateY(18px) scale(.97); }
  to { opacity: 1; transform: none; }
}

.kicker {
  margin: 16px 0 6px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .38em;
  color: var(--gold);
  text-transform: uppercase;
}
.kicker.danger { color: #ff8a93; margin-top: 4px; }

h1 {
  margin: 4px 0 14px;
  font-family: var(--hud-font);
  font-size: clamp(46px, 10.5vh, 76px);
  font-weight: 900;
  line-height: .82;
  letter-spacing: .015em;
  text-transform: uppercase;
  text-shadow: 0 6px 0 rgba(0, 0, 0, .22), 0 16px 36px rgba(0, 0, 0, .3);
}
h1 em {
  font-style: normal;
  color: var(--red);
  text-shadow: 0 6px 0 rgba(0, 0, 0, .22), 0 0 40px rgba(244, 42, 65, .32);
}

h2 {
  margin: 6px 0 12px;
  font-size: clamp(48px, 9vh, 68px);
  font-weight: 900;
  line-height: .9;
  letter-spacing: .02em;
  color: var(--red);
  text-shadow: 0 6px 0 rgba(0, 0, 0, .22);
}

.tagline {
  margin: 0 auto 20px;
  max-width: 340px;
  font-size: 13px;
  line-height: 1.55;
  font-weight: 600;
  color: rgba(255, 247, 230, .72);
}
.over-card .tagline { margin-bottom: 22px; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  padding: 16px 22px;
  border: 0;
  border-radius: 14px;
  font-family: inherit;
  font-size: 15px;
  font-weight: 900;
  letter-spacing: .16em;
  text-transform: uppercase;
  cursor: pointer;
  transition: transform .14s ease, box-shadow .14s ease, filter .14s ease;
}
.btn.primary {
  color: #fff;
  background: linear-gradient(180deg, #13a862, #067a4c);
  box-shadow: 0 7px 0 #034a2f, 0 16px 30px rgba(0, 0, 0, .38), inset 0 1px 0 rgba(255, 255, 255, .3);
  text-shadow: 0 1px 0 rgba(0, 0, 0, .25);
}
.btn.primary span { color: var(--gold); font-size: 20px; line-height: 0; }
.btn.primary:hover { filter: brightness(1.08); transform: translateY(-1px); }
.btn.primary:active { transform: translateY(4px); box-shadow: 0 3px 0 #034a2f, 0 8px 18px rgba(0, 0, 0, .3); }

.hints {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px 14px;
  margin: 16px 0 0;
  font-size: 10.5px;
  line-height: 1.6;
  font-weight: 700;
  letter-spacing: .06em;
  color: rgba(255, 247, 230, .55);
}
kbd {
  display: inline-block;
  min-width: 18px;
  padding: 2px 5px;
  margin: 0 1px;
  border-radius: 4px;
  border: 1px solid rgba(255, 247, 230, .25);
  border-bottom-width: 2px;
  background: rgba(255, 247, 230, .08);
  font-family: inherit;
  font-size: 9px;
  font-weight: 900;
  color: rgba(255, 247, 230, .85);
  line-height: 1.2;
}

.hazard-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 18px 0 12px;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .16em;
  color: rgba(255, 247, 230, .5);
}
.hazard-row i { flex: 1; height: 1px; background: rgba(255, 247, 230, .14); }

.best-line {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .24em;
  color: rgba(255, 247, 230, .45);
}
.best-line b { color: var(--gold); font-size: 13px; margin-left: 6px; font-variant-numeric: tabular-nums; }

.score-pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin: 0 0 22px;
}
.score-pair div {
  padding: 12px 8px;
  border-radius: 14px;
  border: 1px solid rgba(255, 247, 230, .12);
  background: rgba(0, 0, 0, .18);
}
.score-pair span {
  display: block;
  font-size: 8.5px;
  font-weight: 900;
  letter-spacing: .3em;
  color: rgba(255, 247, 230, .5);
  margin-bottom: 4px;
}
.score-pair b {
  display: block;
  font-size: clamp(28px, 5vh, 38px);
  font-weight: 900;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  color: var(--cream);
}
.score-pair div:last-child b { color: var(--gold); }

@media (max-height: 620px) {
  .menu-card { padding-top: 20px; padding-bottom: 18px; border-radius: 20px; }
  .kicker { margin-top: 8px; }
  h1 { font-size: clamp(38px, 11vh, 56px); margin-bottom: 10px; }
  h2 { font-size: clamp(38px, 10vh, 54px); }
  .tagline { margin-bottom: 14px; font-size: 12px; }
  .hazard-row { margin: 12px 0 8px; }
  .hints { margin-top: 10px; }
  .flag-lg { width: 58px; height: 37px; }
  .flag-lg::after { width: 16px; height: 16px; }
  .score-pair { margin-bottom: 16px; }
}

@media (max-width: 420px) {
  .brand { display: none; }
  .hud { padding-left: 10px; padding-right: 10px; }
  .scoreboard { padding-left: 16px; padding-right: 16px; }
  .speedo { display: none; }
  .steer { width: 62px; height: 62px; }
  .menu-card { border-radius: 22px; }
}

