const Sound = {
 ac:null, master:null, engineGain:null, osc:[], enabled:true,
 init() {
  if (this.ac) { if(this.ac.state==='suspended') this.ac.resume(); return; }
  const AC = window.AudioContext || window.webkitAudioContext;
  if(!AC) return;
  this.ac = new AC();
  this.master = this.ac.createGain(); this.master.gain.value = this.enabled?0.7:0; this.master.connect(this.ac.destination);
  // engine chain
  const g = this.ac.createGain(); g.gain.value=0;
  const filt = this.ac.createBiquadFilter(); filt.type='lowpass'; filt.frequency.value=420; filt.Q.value=2;
  g.connect(filt); filt.connect(this.master);
  this.engineGain = g;
  this.engineFilter = filt;
  const o1 = this.ac.createOscillator(); o1.type='sawtooth'; o1.frequency.value=52;
  const o2 = this.ac.createOscillator(); o2.type='square'; o2.frequency.value=39;
  const og2 = this.ac.createGain(); og2.gain.value=.4;
  o1.connect(g); o2.connect(og2); og2.connect(g);
  o1.start(); o2.start();
  this.osc=[o1,o2];
  // lfo for chug
  const lfo = this.ac.createOscillator(); lfo.frequency.value=7; const lg=this.ac.createGain(); lg.gain.value=6; lfo.connect(lg); lg.connect(o1.frequency); lfo.start();
  this.lfo=lfo;
 },
 startEngine(){ this.init(); if(!this.ac) return; this.ac.resume(); const t=this.ac.currentTime; this.engineGain.gain.cancelScheduledValues(t); this.engineGain.gain.setTargetAtTime(.045,t,.15); },
 stopEngine(){ if(!this.ac)return; this.engineGain.gain.setTargetAtTime(0,this.ac.currentTime,.1); },
 setSpeed(px){ if(!this.ac)return; const f=44+px*.028; const t=this.ac.currentTime; this.osc[0].frequency.setTargetAtTime(f,t,.2); this.osc[1].frequency.setTargetAtTime(f*.76,t,.2); this.engineFilter.frequency.setTargetAtTime(320+px*.5,t,.2); if(this.lfo) this.lfo.frequency.setTargetAtTime(6+px*.01,t,.3); },
 horn(){ ... },
 crash(){ ... },
 toggle(){ this.enabled=!this.enabled; if(this.master) this.master.gain.setTargetAtTime(this.enabled?.7:0, this.ac.currentTime, .05); return enabled; }
}

