   let y=srand()*200 - 100;
   while(y<period){
     const r=srand();
     let type;
     if(r<.24) type='tree';
     else if(r<.42) type='palm';
     else if(r<.62) type='grass';
     else if(r<.72) type='pole';
     else if(r<.82 && roadX>95) type='hut';
     else if(r<.9 && roadX>70) type='pond';
     else if(roadX>60) type='paddy';
     else type='grass';
     const depth = type==='pole' ? srand()*0.18 : .15+srand()*.8;
     scenery.push({side, y, type, depth, v:srand(), phase:srand()*TAU});
     y += 55+srand()*145;
   }
 }
}
