+    ctx.lineWidth = Math.max(2, w * 0.045);
+    ctx.beginPath();
+    ctx.moveTo(-w * 0.32, l * 0.33);
+    ctx.lineTo(w * 0.32, l * 0.33);
+    ctx.stroke();
+
+    // front lamp
+    ctx.fillStyle = "#ffeaa8";
+    circle(0, l * 0.38, w * 0.05);
+  }
+
+  // ------------------------------- player -------------------------------
+  function drawPlayer(t) {
+    const bob = state.mode === "playing" ? Math.sin(t * 11) * 1.2 : Math.sin(t * 3) * 0.6;
+    const w = bike.w,
+      h = bike.h;
+    ctx.save();
+    ctx.translate(player.x, playerY + bob);
+    ctx.rotate(player.lean + player.angle);
+
+    // shadow
+    ctx.fillStyle = "rgba(0,0,0,.3)";
+    ellipse(3, 4, w * 0.44, h * 0.42);
+
+    // wheels
+    ctx.fillStyle = "#141617";
+    pathRound(-w * 0.13, -h * 0.46, w * 0.26, h * 0.22, w * 0.1);
+    ctx.fill();
+    pathRound(-w * 0.15, h * 0.25, w * 0.3, h * 0.2, w * 0.1);
+    ctx.fill();
+    ctx.fillStyle = "#4d5456";
+    ctx.fillRect(-w * 0.03, -h * 0.43, w * 0.06, h * 0.15);
+    ctx.fillRect(-w * 0.03, h * 0.28, w * 0.06, h * 0.13);
+
+    // exhaust
+    ctx.strokeStyle = "#b8c1c4";
+    ctx.lineWidth = Math.max(1.5, w * 0.07);
+    ctx.beginPath();
+    ctx.moveTo(w * 0.24, h * 0.08);
+    ctx.lineTo(w * 0.27, h * 0.4);
+    ctx.stroke();
+
+    // frame / body
+    const bg = ctx.createLinearGradient(-w / 2, 0, w / 2, 0);
+    bg.addColorStop(0, "#a50f1c");
+    bg.addColorStop(0.5, "#e63946");
+    bg.addColorStop(1, "#8d0a15");
+    ctx.fillStyle = bg;
+    pathRound(-w * 0.3, -h * 0.22, w * 0.6, h * 0.5, w * 0.14);
+    ctx.fill();
+
+    // front cowl
+    ctx.fillStyle = "#c9202e";
+    pathRound(-w * 0.26, -h * 0.37, w * 0.52, h * 0.19, w * 0.12);
+    ctx.fill();
+
+    // handlebar
+    ctx.strokeStyle = "#26292a";
+    ctx.lineWidth = Math.max(2, w * 0.09);
+    ctx.beginPath();
+    ctx.moveTo(-w * 0.55, -h * 0.24);
+    ctx.lineTo(w * 0.55, -h * 0.24);
+    ctx.stroke();
+    ctx.fillStyle = "#111313";
+    circle(-w * 0.55, -h * 0.24, w * 0.075);
+    circle(w * 0.55, -h * 0.24, w * 0.075);
+
+    // headlamp
+    ctx.fillStyle = "#fff4c2";
+    circle(0, -h * 0.42, w * 0.1);
+    ctx.fillStyle = "rgba(255,255,255,.9)";
+    circle(0, -h * 0.425, w * 0.04);
+
+    // tail light
+    ctx.fillStyle = "#ff5252";
+    pathRound(-w * 0.12, h * 0.42, w * 0.24, h * 0.035, 2);
+    ctx.fill();
+
+    // rider legs
+    ctx.fillStyle = "#143b2c";
+    ellipse(-w * 0.26, h * 0.03, w * 0.12, h * 0.12);
+    ellipse(w * 0.26, h * 0.03, w * 0.12, h * 0.12);
+
+    // rider torso
+    const tg = ctx.createLinearGradient(-w * 0.4, 0, w * 0.4, 0);
+    tg.addColorStop(0, "#087a4a");
+    tg.addColorStop(0.5, "#12a05f");
+    tg.addColorStop(1, "#06603a");
+    ctx.fillStyle = tg;
+    ellipse(0, h * 0.02, w * 0.4, h * 0.21);
+
+    // arms
+    ctx.strokeStyle = "#0b8450";
+    ctx.lineWidth = Math.max(2.5, w * 0.1);
+    ctx.lineCap = "round";
+    ctx.beginPath();
+    ctx.moveTo(-w * 0.25, -h * 0.04);
+    ctx.lineTo(-w * 0.5, -h * 0.21);
+    ctx.moveTo(w * 0.25, -h * 0.04);
+    ctx.lineTo(w * 0.5, -h * 0.21);
+    ctx.stroke();
+
+    // helmet
+    const hg = ctx.createRadialGradient(-w * 0.1, -h * 0.13, 1, 0, -h * 0.09, w * 0.35);
+    hg.addColorStop(0, "#ff5b63");
+    hg.addColorStop(0.55, "#e21f2f");
+    hg.addColorStop(1, "#9e0f1b");
+    ctx.fillStyle = hg;
+    circle(0, -h * 0.09, w * 0.33);
+    ctx.strokeStyle = "rgba(70,5,10,.35)";
+    ctx.lineWidth = 1;
+    ctx.stroke();
+    // visor
+    ctx.strokeStyle = "#2b3238";
+    ctx.lineWidth = Math.max(2, w * 0.08);
+    ctx.beginPath();
+    ctx.arc(0, -h * 0.094, w * 0.23, -Math.PI * 0.82, -Math.PI * 0.18);
+    ctx.stroke();
+    // flag-green shoulder flash
+    ctx.fillStyle = "rgba(255,247,230,.85)";
+    pathRound(-w * 0.09, -h * 0.02, w * 0.18, h * 0.035, 2);
+    ctx.fill();
+
+    ctx.restore();
+  }
+
+  // ---------------------------- ground & road ---------------------------
+  function drawGround(t) {
+    ctx.fillStyle = groundGrad;
+    ctx.fillRect(0, 0, W, H);
+
+    const bandH = 190;
+    const off = mod(state.scroll * 0.55, bandH * 2);
+    ctx.fillStyle = "rgba(255,241,160,.035)";
+    for (let y = -bandH * 2 + off; y < H + bandH; y += bandH * 2) {
+      ctx.fillRect(0, y, W, bandH);
+    }
+
+    // faint field furrows on the shoulders
+    ctx.strokeStyle = "rgba(22,78,30,.16)";
+    ctx.lineWidth = 1;
+    const furrowGap = 34;
+    const foff = mod(state.scroll * 0.55, furrowGap);
+    for (let y = -furrowGap + foff; y < H + furrowGap; y += furrowGap) {
+      ctx.beginPath();
+      ctx.moveTo(0, y);
+      ctx.lineTo(Math.max(0, roadX - 16), y + 7);
+      ctx.moveTo(Math.min(W, roadX + roadW + 16), y + 4);
+      ctx.lineTo(W, y - 3);
+      ctx.stroke();
+    }
+  }
+
+  function drawRoad(t) {
+    // dirt shoulders
+    ctx.fillStyle = "#7c6542";
+    ctx.fillRect(roadX - 9, 0, 9, H);
+    ctx.fillRect(roadX + roadW, 0, 9, H);
+    ctx.fillStyle = "rgba(30,24,15,.22)";
+    ctx.fillRect(roadX - 2, 0, 2, H);
+    ctx.fillRect(roadX + roadW, 0, 2, H);
+
+    // asphalt
+    ctx.fillStyle = roadGrad;
+    ctx.fillRect(roadX, 0, roadW, H);
+
+    ctx.save();
+    ctx.beginPath();
+    ctx.rect(roadX, 0, roadW, H);
+    ctx.clip();
+    ctx.translate(0, mod(state.scroll, 220));
+    if (asphaltPattern) {
+      ctx.fillStyle = asphaltPattern;
+      ctx.fillRect(roadX, -220, roadW, H + 440);
+    }
+    ctx.restore();
+
+    // tire tracks
+    ctx.fillStyle = "rgba(10,12,12,.07)";
+    for (let i = 0; i < 4; i++) {
+      const x = laneX(i);
+      ctx.fillRect(x - laneW * 0.26, 0, laneW * 0.15, H);
+      ctx.fillRect(x + laneW * 0.11, 0, laneW * 0.15, H);
+    }
+
+    // lane markings
+    const lw = Math.max(3, laneW * 0.032);
+    const dash = laneW * 0.34;
+    const gap = laneW * 0.28;
+    ctx.strokeStyle = "rgba(246,243,230,.82)";
+    ctx.lineWidth = lw;
+    ctx.lineCap = "butt";
+    ctx.setLineDash([dash, gap]);
+    ctx.lineDashOffset = -mod(state.scroll, dash + gap);
+    for (const i of [1, 3]) {
+      const x = roadX + laneW * i;
+      ctx.beginPath();
+      ctx.moveTo(x, 0);
+      ctx.lineTo(x, H);
+      ctx.stroke();
+    }
+    ctx.setLineDash([]);
+
+    // centre double yellow
+    ctx.strokeStyle = "rgba(238,190,74,.9)";
+    ctx.lineWidth = Math.max(2, laneW * 0.02);
+    for (const dx of [-laneW * 0.045, laneW * 0.045]) {
+      const x = roadX + laneW * 2 + dx;
+      ctx.beginPath();
+      ctx.moveTo(x, 0);
+      ctx.lineTo(x, H);
+      ctx.stroke();
+    }
+
+    // solid edge lines
+    ctx.strokeStyle = "rgba(246,243,230,.9)";
+    ctx.lineWidth = Math.max(2.5, laneW * 0.026);
+    for (const x of [roadX + laneW * 0.055, roadX + roadW - laneW * 0.055]) {
+      ctx.beginPath();
+      ctx.moveTo(x, 0);
+      ctx.lineTo(x, H);
+      ctx.stroke();
+    }
+
+    // edge rumble strips
+    const seg = Math.max(12, laneW * 0.15);
+    const rOff = mod(state.scroll, seg * 2);
+    for (let y = -seg * 2 + rOff; y < H + seg; y += seg * 2) {
+      ctx.fillStyle = "rgba(214,69,61,.7)";
+      ctx.fillRect(roadX + 2, y, Math.max(3, laneW * 0.02), seg);
+      ctx.fillRect(roadX + roadW - 2 - Math.max(3, laneW * 0.02), y + seg, Math.max(3, laneW * 0.02), seg);
+    }
+
+    // occasional road patch
+    const patchOff = mod(state.scroll * 1, 900);
+    ctx.fillStyle = "rgba(15,17,17,.12)";
+    for (let i = 0; i < 3; i++) {
+      const py = mod(i * 337 - patchOff, 900) - 120;
+      const px = roadX + laneW * (0.6 + i * 1.2);
+      ctx.beginPath();
+      ctx.ellipse(px, py, laneW * 0.22, laneW * 0.12, i, 0, TAU);
+      ctx.fill();
+    }
+  }
+
+  // ------------------------------- effects ------------------------------
+  function drawStreaks() {
+    ctx.save();
+    ctx.strokeStyle = "rgba(255,255,255,.22)";
+    ctx.lineWidth = 1.4;
+    for (const s of streaks) {
+      ctx.globalAlpha = s.a;
+      ctx.beginPath();
+      ctx.moveTo(s.x, s.y);
+      ctx.lineTo(s.x, s.y + s.len);
+      ctx.stroke();
+    }
+    ctx.restore();
+  }
+
+  function drawParticles() {
+    for (const p of particles) {
+      const a = clamp(p.life / p.max, 0, 1);
+      ctx.globalAlpha = a * p.alpha;
+      ctx.fillStyle = p.color;
+      if (p.kind === "smoke") {
+        const r = p.size * (1.8 - a * 0.8);
+        circle(p.x, p.y, r);
+      } else {
+        circle(p.x, p.y, p.size);
+      }
+    }
+    ctx.globalAlpha = 1;
+  }
+
+  function drawFloats() {
+    ctx.save();
+    ctx.textAlign = "center";
+    ctx.textBaseline = "middle";
+    for (const f of floats) {
+      const a = clamp(f.life / f.max, 0, 1);
+      ctx.globalAlpha = a;
+      ctx.font = `900 ${f.size}px Lato, Arial, sans-serif`;
+      ctx.fillStyle = "rgba(0,0,0,.35)";
+      ctx.fillText(f.text, f.x + 1, f.y + 2);
+      ctx.fillStyle = f.color;
+      ctx.fillText(f.text, f.x, f.y);
+    }
+    ctx.restore();
+    ctx.globalAlpha = 1;
+  }
+
+  /* @@PART3@@ */
 })();

content.text:
Now part 3: audio, spawn/update logic, input, render, init. Need to ensure functions referenced: addFloat, spawnWave etc. Let's write.

Audio object:

```
const Sound = {
 ctx:null, master:null, engineGain:null, engineOsc:null, engineOsc2:null, filter:null, started:false,
 init() {
  if (this.ctx) { if(this.ctx.state==='suspended') this.ctx.resume(); return; }
  const AC = window.AudioContext||window.webkitAudioContext; if(!AC) return;
  const ac=new AC(); this.ctx=ac;
  const master=ac.createGain(); master.gain.value=soundOn?0.9:0; master.connect(ac.destination); this.master=master;
  // engine
  const g=ac.createGain(); g.gain.value=0; g.connect(master);
  const filt=ac.createBiquadFilter(); filt.type='lowpass'; filt.frequency.value=320; filt.Q.value=2; filt.connect(g);
  const o1=ac.createOscillator(); o1.type='sawtooth'; o1.frequency.value=54;
  const o2=ac.createOscillator(); o2.type='square'; o2.frequency.value=41;
  const g2=ac.createGain(); g2.gain.value=.5; 
  o1.connect(filt); o2.connect(g2); g2.connect(filt);
  o1.start(); o2.start();
  this.engine={gain:g, filter:filt, o1,o2};
  this.started=true;
 },
 startEngine(){ init; if (!this.engine)return; const t=ctx.currentTime; gain.gain.cancelScheduledValues(t); gain.gain.setTargetAtTime(0.028, t, .2); },
 setSpeed(px){ ... o1.frequency.setTargetAtTime(46+px*.035,...); o2 freq =*0.75; filter frequency 220+px*.4; },
 stopEngine(){ gain.gain.setTargetAtTime(0, now, .08); },
 pauseEngine(){...},
 crash(){ init; noise buffer ... },
 horn(){ ... },
 toggle(){ soundOn=!soundOn; if(master) master.gain.setTargetAtTime(soundOn?.9:0,now,.05); update button; localStorage save }
}
```
Careful engineGain ramp from 0 to .028; engine might be loud but okay.

Crash noise:
```
const dur=.8; const buf=ctx.createBuffer(1, ctx.sampleRate*dur, ctx.sampleRate); const d=buf.getChannelData(0); for i d[i]=(Math.random()*2-1)*Math.pow(1-i/len,2);
const src=ctx.createBufferSource(); src.buffer=buf;
const f=ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=1800;
const g=ctx.createGain(); g.gain.setValueAtTime(.45,now); g.gain.exponentialRampToValueAtTime(.001, now+dur);
src.connect(f);f.connect(g);g.connect(master);src.start();
// thud
osc sine 90→35, gain .4→.001
```
Master gain if soundOn .9. fine.

Horn:
```
function horn(){ if(!ctx) return; const t=ctx.currentTime; [392,466].forEach((f,i)=>{osc square, gain env 0..0.05..0 at t+i*.09?})}
```
Actually two-tone duplicate auto horn. Do two oscillators simultaneously for chord 370/466 for .18s, two beeps separated .22s. Keep volume .05.

Mute button text: '♪' / '♪' with muted class. Use aria-label update.

Spawning:
```
const TYPE_DIM={bus:{wf:.82,lf:2.5,on:[95,145]}, cng:{wf:.76,lf:1.3,on:[140,205]}, tomtom:{wf:.74,lf:1.5,on:[150,215]}, rickshaw:{wf:.64,lf:1.3,on:[85,145]}};
function pickVehicleType(){const r=Math.random(); if(r<.28)return 'cng'; if(r<.53)return 'rickshaw'; if(r<.8)return 'tomtom'; return 'bus';}
function spawnVehicle(lane, opts={}){
 const type = opts.type||pickVehicleType();
 const d=TYPE_DIM[type]; const w=laneW*d.wf; const l=laneW*d.lf;
 const palette = type==='bus'?pick(BUS_PALETTES):type==='tomtom'?pick(TOMTOM_PALETTES):type==='rickshaw'?pick(RICKSHAW_PALETTES):null;
 const v={type,lane,w,l,x:laneX(lane)+rand(-laneW*.04,laneW*.04),y:-l/2-rand(20,60),sway:rand(0,TAU),onSpeed:rand(d.on[0],d.on[1]),palette,passed:false};
 vehicles.push(v); return v;
}
```
For cng palette null but draw uses only type dims; fine.

spawnWave as described. Need avoid impossible: shuffle. Also ensure not all 3 blocked at low level. count based on level. For extra fairness, if count===3 and Math.random()<0.35 use 2? just weights.

Also spacing: if vehicles at y < laneW*1.2 in same lane, skip lane (rare).
`const available = [0,1,2,3].filter(l=>!vehicles.some(v=>v.lane===l && v.y < v.l*0.6 + 40));` but newly spawned at top. Maybe not needed.

Wave count and blocked:
```
let count;
const r=Math.random();
if(level<3) count = r<.8?1:2;
else if(level<6) count = r<.5?1:2;
else count = r<.3?1:r<.82?2:3;
count = Math.min(count,3);
const lanes=shuffle([0,1,2,3]).slice(0,count);
lanes.forEach((lane,i)=> setTimeout? no; spawn with stagger y: spawnVehicle(lane,{stagger:i*rand(30,80)})...
