Render:
```
function render(t){
 ctx.setTransform(DPR,0,0,DPR,0,0);
 ctx.clearRect(0,0,W,H);
 ctx.save();
 if(state.shake>0){ctx.translate(rand(-1,1)*state.shake*.5, rand(-1,1)*state.shake*.5);}
 drawGround(t); drawScenery(t); drawRoad(t); drawStreaks();
