  // -------------------------------- audio --------------------------------
  const Sound = {
    ctx: null,
    master: null,
    engine: null,
    init() {
      if (this.ctx) {
        if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
        return;
      }
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      try {
        const ac = new AC();
        this.ctx = ac;
        const master = ac.createGain();
        master.gain.value = soundOn ? 0.85 : 0;
        master.connect(ac.destination);
        this.master = master;

        const gain = ac.createGain();
        gain.gain.value = 0;
        gain.connect(master);

        const filter = ac.createBiquadFilter();
        filter.type = "lowpass";
        filter.frequency.value = 300;
        filter.Q.value = 1.5;
        filter.connect(gain);

        const o1 = ac.createOscillator();
        o1.type = "sawtooth";
        o1.frequency.value = 54;
        const o2 = ac.createOscillator();
        o2.type = "square";
        o2.frequency.value = 41;
        const o2g = ac.createGain();
        o2g.gain.value = 0.45;

        o1.connect(filter);
        o2.connect(o2g);
        o2g.connect(filter);
        o1.start();
        o2.start();
        this.engine = { gain, filter, o1, o2 };
      } catch (_) {
        this.ctx = null;
      }
    },
    startEngine() {
      this.init();
      if (!this.ctx || !this.engine) return;
      if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
      const now = this.ctx.currentTime;
      this.engine.gain.gain.cancelScheduledValues(now);
      this.engine.gain.gain.setTargetAtTime(0.026, now, 0.25);
    },
    stopEngine(quick) {
      if (!this.ctx || !this.engine) return;
      const now = this.ctx.currentTime;
      this.engine.gain.gain.cancelScheduledValues(now);
      this.engine.gain.gain.setTargetAtTime(0, now, quick ? 0.03 : 0.18);
    },
