  await page.locator('#startBtn').click();
  await page.waitForTimeout(1200);
  const started = await page.locator('body').getAttribute('data-state');
  const scoreAfterStart = Number(await page.locator('#score').textContent());
  await page.keyboard.press('ArrowLeft');
  await page.waitForTimeout(350);
  const pauseLane = await page.evaluate(() => ({state: document.body.dataset.state, score: document.querySelector('#score').textContent}));
  await page.locator('#pauseBtn').click();
  const pausedState = await page.locator('body').getAttribute('data-state');
  const pausedScore = await page.locator('#score').textContent();
  await page.waitForTimeout(850);
  const frozenScore = await page.locator('#score').textContent();
  await page.keyboard.press('p');
  const resumedState = await page.locator('body').getAttribute('data-state');
  await page.waitForTimeout(700);
  await page.screenshot({path:'/tmp/opencode/latest.jpg', type:'jpeg', quality:78});
  let outcome = await page.locator('body').getAttribute('data-state');
  const deadline = Date.now() + 30000;
  while (outcome !== 'over' && Date.now() < deadline) {
    await page.waitForTimeout(500);
    outcome = await page.locator('body').getAttribute('data-state');
  }
  let overText = null;
  if (outcome === 'over') {
    overText = await page.locator('#crashText').textContent();
    await page.locator('#restartBtn').click();
    const restarted = await page.locator('body').getAttribute('data-state');
    console.log(JSON.stringify({started,scoreAfterStart,pauseLane,pausedState,pausedScore,frozenScore,resumedState,outcome,overText,restarted,errors},null,2));
  } else {
    console.log(JSON.stringify({started,scoreAfterStart,pauseLane,pausedState,pausedScore,frozenScore,resumedState,outcome,errors},null,2));
  }
  await browser.close();
})().catch(err => { console.error(err); process.exit(1); });
